import{_ as l,E as t,h as s,c as p,b as a,f as r,H as n,w as i,l as u,a3 as h,a4 as m}from"./chunks/framework.B_fYP6Of.js";const S=JSON.parse('{"title":"Backend architecture draft","description":"Review the proposed Rust chat backend, the worker responsible for each run, and the conditions under which one answer may finish or fail.","frontmatter":{"title":"Backend architecture draft","description":"Review the proposed Rust chat backend, the worker responsible for each run, and the conditions under which one answer may finish or fail.","teaser":"A reader clicks Cancel just as the last answer arrives. Which part of the system gets to decide what the conversation records?"},"headers":[],"relativePath":"architecture/backend.md","filePath":"architecture/backend.md"}'),b={name:"architecture/backend.md"};function v(f,e,g,w,k,y){const o=t("LabArticleHeader"),d=t("Mermaid"),c=t("LabScroll");return s(),p("div",null,[e[1]||(e[1]=a("h1",{id:"backend-architecture-draft",tabindex:"-1"},[r("Backend architecture draft "),a("a",{class:"header-anchor",href:"#backend-architecture-draft","aria-label":'Permalink to "Backend architecture draft"'},"​")],-1)),n(o),e[2]||(e[2]=a("p",null,"A student opens a question, starts receiving a cited answer, and hits Cancel. At almost the same moment, the model sends its final response. The browser and the worker have seen different events. One owner has to decide which outcome becomes part of the record.",-1)),e[3]||(e[3]=a("p",null,"This design draft assigns that responsibility and describes the failure cases a future implementation must pass. The services and performance measurements remain proposed.",-1)),e[4]||(e[4]=a("h2",{id:"serving-and-enrichment-boundaries",tabindex:"-1"},[r("Serving and enrichment boundaries "),a("a",{class:"header-anchor",href:"#serving-and-enrichment-boundaries","aria-label":'Permalink to "Serving and enrichment boundaries"'},"​")],-1)),e[5]||(e[5]=a("p",null,"In the draft, Rust with Axum/Tokio handles authenticated chat, retrieves evidence, and owns the lifecycle of a streamed answer. Python workers parse and enrich documents in a separate dependency graph. NATS JetStream carries durable background events. SQLite remains a candidate for retrieval. Splitting chat from enrichment is a way to test whether a slow import can stop delaying a reader’s answer. End-to-end measurements would establish the effect.",-1)),n(c,{kind:"diagram",label:"diagram for Serving and enrichment boundaries"},{default:i(()=>[(s(),u(h,null,{default:i(()=>[n(d,{id:"mermaid-17",class:"mermaid",graph:"flowchart%20LR%0A%20%20accTitle%3A%20Run%20ownership%20and%20index%20publication%0A%20%20accDescr%3A%20Axum%20passes%20browser%20commands%20to%20the%20run%20owner%2C%20which%20retrieves%20evidence%2C%20calls%20the%20model%2C%20and%20streams%20events.%20A%20separate%20ingestion%20workflow%20publishes%20searchable%20projections%20and%20records%20event%20intent%20in%20an%20outbox.%0A%20%20UI%5BBrowser%5D%20--%3E%7CHTTP%20commands%7C%20API%5BAxum%20adapters%5D%0A%20%20API%20--%3E%20UC%5BChat%20use%20cases%20and%20run%20owner%5D%0A%20%20UC%20--%3E%7CDirect%20SSE%7C%20UI%0A%20%20UC%20--%3E%20RP%5BRetrieval%20port%5D%0A%20%20RP%20--%3E%20DB%5BLocal%20SQLite%20candidate%5D%0A%20%20UC%20--%3E%20MP%5BModel%20provider%20port%5D%0A%20%20UC%20--%3E%20RS%5BRun%20store%20and%20optional%20replay%20log%5D%0A%20%20SRC%5BSource%20revisions%5D%20--%3E%20WF%5BETL%20orchestrator%3A%20unresolved%5D%0A%20%20WF%20--%3E%20PY%5BPython%20NLP%20workers%5D%0A%20%20PY%20--%3E%20PUB%5BVersioned%20projection%20publisher%5D%0A%20%20PUB%20--%3E%20DB%0A%20%20PUB%20--%3E%20OUT%5BTransactional%20outbox%5D%0A%20%20OUT%20--%3E%20JS%5BNATS%20JetStream%5D%0A%20%20JS%20--%3E%20WF%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1}))]),_:1}),e[6]||(e[6]=m('<p>Axum provides SSE response primitives, including event streams and keepalives. The browser reaches this endpoint directly through a streaming-capable ingress; no frontend application server or broker is required to relay ordinary token deltas. <a href="https://docs.rs/axum/latest/axum/response/sse/index.html" target="_blank" rel="noreferrer">Axum SSE</a></p><h2 id="domain-and-application-contracts" tabindex="-1">Domain and application contracts <a class="header-anchor" href="#domain-and-application-contracts" aria-label="Permalink to &quot;Domain and application contracts&quot;">​</a></h2><p>A tenant, conversation, run, generation attempt, source revision, chunk, and evidence record each need distinct identifiers. Validate those identifiers at the boundary. An evidence reference must lead back to immutable source bytes, the revision, and a location a reviewer can inspect. Preserve polarity, time qualifiers, and extraction history when a relationship becomes a graph claim.</p><p>Use cases include starting a run, retrieving evidence, streaming events, canceling a run, and publishing an enrichment revision. Their ports cover authorization, retrieval, model generation, run persistence, artifact storage, and event publication. Axum, SQLite, provider HTTP clients, and NATS implement adapters. Keep domain rules independent of transport DTOs and database rows; introduce traits at real substitution or testing boundaries rather than wrapping every function.</p><p>Expected outcomes use explicit errors: invalid input, unauthorized access, conflict, overload, unavailable dependency, deadline, and cancellation. Provider failures remain distinguishable from empty retrieval. HTTP mappings and sanitized diagnostic fields belong in adapters.</p><h2 id="runs-streaming-and-ownership" tabindex="-1">Runs, streaming, and ownership <a class="header-anchor" href="#runs-streaming-and-ownership" aria-label="Permalink to &quot;Runs, streaming, and ownership&quot;">​</a></h2><p>A start command accepts an idempotency key and returns a run identifier. A run has one authoritative owner and an increasing attempt epoch. Before multiple serving replicas are enabled, the run-store adapter must support atomic ownership acquisition, lease renewal, and fencing checks on every authoritative write. A lease alone cannot prevent an expired owner from publishing stale results.</p><p>Run states are accepted, retrieving, generating, and one terminal outcome: completed, canceled, failed, or interrupted. Events carry run ID, attempt epoch, sequence number, type, and payload. Sources, status changes, text deltas, and terminal outcomes are separate event types. Stop is an authenticated HTTP command; the browser closing an SSE connection is a transport event. The disconnect continuation/grace policy remains an explicit product decision.</p><p>Direct streaming is the default. Cross-device continuation, multiple viewers, and reconnect replay require an optional retained per-run output log with a specified retention and durability policy. Resume reads after a sequence and deduplicates overlap with live delivery. Replaying stored output cannot resume a lost model inference state. A failed generation worker produces an interrupted attempt or an explicitly new continuation attempt, never silent regeneration presented as the same stream.</p><h2 id="deadlines-and-resource-ownership" tabindex="-1">Deadlines and resource ownership <a class="header-anchor" href="#deadlines-and-resource-ownership" aria-label="Permalink to &quot;Deadlines and resource ownership&quot;">​</a></h2><p>Propagate one request budget into stage deadlines for retrieval, reranking, provider connection, first output, and idle streaming. Independent retrieval operations may overlap. Avoid mandatory serial model-based query rewriting for ordinary requests.</p><p>Each run owns its child-task handles and cancellation token. Cancellation stops local work, closes provider streams, and invokes a provider cancellation facility when supported; remote computation or billing may continue. Dropping a future does not automatically stop independently spawned tasks. Shutdown stops admission, signals cancellation, then joins tracked tasks within an operational deadline. <a href="https://tokio.rs/tokio/tutorial/select" target="_blank" rel="noreferrer">Tokio cancellation</a>, <a href="https://tokio.rs/tokio/topics/shutdown" target="_blank" rel="noreferrer">shutdown</a></p><p>Set bounded admission queues, concurrent-run permits, provider permits, event-buffer bytes, payload sizes, and graph-expansion limits. Slow subscribers receive a resumable disconnect when retention permits, or a defined failure. They cannot accumulate unlimited output. Separate ingestion and chat capacity. Numeric limits and latency objectives require representative load tests.</p><h2 id="retrieval-and-publication" tabindex="-1">Retrieval and publication <a class="header-anchor" href="#retrieval-and-publication" aria-label="Permalink to &quot;Retrieval and publication&quot;">​</a></h2><p>SQLite can colocate canonical chunks, FTS5 BM25, vector indexes, and typed adjacency tables. Fuse independently ranked lexical/vector candidates; evaluate bounded graph expansion against the same baseline. FTS5 relevance sorts ascending, so lower BM25 values are better. <a href="https://www.sqlite.org/fts5.html" target="_blank" rel="noreferrer">FTS5</a></p><p>Vector selection remains open: stable sqlite-vec exact search, its prerelease DiskANN path, and SQLite&#39;s distinct Vec1 ANN extension require recall, filtering, update, and latency comparisons. Do not assume arbitrary SQL filters execute inside a vector index. <a href="https://github.com/asg017/sqlite-vec/releases" target="_blank" rel="noreferrer">sqlite-vec releases</a>, <a href="https://www.sqlite.org/vec1.html" target="_blank" rel="noreferrer">Vec1</a></p><p>The initial SQLite topology is a local retrieval owner with serialized writes and a bounded pool of database threads/read connections. WAL permits concurrent readers and a writer, but only one writer at a time, and requires same-host access. Long reads can delay checkpoints. Do not mount one writable WAL database across hosts. End retrieval transactions before waiting on model output; carry immutable evidence/version references forward. <a href="https://www.sqlite.org/wal.html" target="_blank" rel="noreferrer">SQLite WAL</a></p><p>Synchronous queries run outside Tokio execution workers. Bound both queued work and active operations; a timeout around a future cannot abort an already-running blocking task. Use supported database interruption/progress mechanisms where appropriate and prevent a late cancellation from interrupting the next borrower of a connection. <a href="https://docs.rs/tokio/latest/tokio/task/fn.spawn_blocking.html" target="_blank" rel="noreferrer">Tokio blocking work</a></p><h2 id="etl-durability-and-decision-gates" tabindex="-1">ETL durability and decision gates <a class="header-anchor" href="#etl-durability-and-decision-gates" aria-label="Permalink to &quot;ETL durability and decision gates&quot;">​</a></h2><p>The DAG publishes separate text, vector, and graph readiness milestones. Its artifacts record source revision, input hashes, parser/chunker versions, model/prompt/schema versions, and dependency identities. Publication checks that the source revision remains current; deletes retract obsolete evidence. Authorization applies to every retrieval branch and evidence fetch.</p><p>Dagster versus Temporal remains unresolved. No custom durable scheduler is promised. The selected orchestrator owns dependencies and workflow recovery; JetStream owns event transport. Consumers tolerate redelivery, commit idempotently, and acknowledge afterward. A transactional outbox closes the database-commit/event-publication gap; it does not create exactly-once external model execution. <a href="https://docs.nats.io/learn/jetstream/delivery-and-acknowledgment" target="_blank" rel="noreferrer">JetStream acknowledgments</a></p><p>Before implementation, settle ownership storage, disconnect/replay guarantees, orchestration, vector extension, and deployment durability. Validate first-useful-token latency, token gaps, cancellation, saturation, filtered recall, ingestion freshness, checkpoint behavior, and crash recovery together.</p>',22))])}const x=l(b,[["render",v]]);export{S as __pageData,x as default};
